/* Keyboard layouts for the kernel's early prompts (keymaps.c; tables generated by gen_keymaps.py from xkeyboard-config:
 * the layouts Aurora offers). Input: Linux key codes from the input layer (PS/2 and USB HID). */
#ifndef NEXUS_KEYMAPS_H
#define NEXUS_KEYMAPS_H
#include "../../kernel/types.h"

struct keymap_state { uint32_t dead; };   /* a pending dead key (combining mark), 0 = none */
/* "de", "us(intl)", "us:intl", "us-intl" or a kbd console name ("uk", "de-latin1", "sv-latin1", "trq", ...); false if
 * unknown (the active layout stays). `source` is only logged. */
bool keymap_select(const char* name, const char* source);
const char* keymap_name(void);    /* the active layout as layout or layout(variant) */
const char* keymap_title(void);   /* "German" */
/* One key press: code points to append (0..2; a dead key alone gives 0, a dead key that does not compose gives its
 * spacing accent + the character). */
unsigned keymap_translate(struct keymap_state* s, unsigned code, bool shift, bool altgr, bool caps, uint32_t out[2]);
unsigned keymap_utf8(uint32_t cp, char out[4]);
/* The system's configured layout: rd.vconsole.keymap= / vconsole.keymap= first; with the root mounted also
 * /etc/vconsole.conf (KEYMAP=), Aurora's /home/nexus/.aurora/keyboard.conf (first of layouts=/variants=) and
 * /etc/default/keyboard (XKBLAYOUT/XKBVARIANT). Selects it (else US) and logs "[64] KEYMAP ...". */
void keymap_configure(bool root_mounted);
/* The layout the mounted root's files configure (no boot options), canonical name; false if none. */
bool keymap_from_files(char* name, unsigned capacity);
/* Canonical name for a configured name ("uk" -> "gb", "us-intl" -> "us(intl)"); false if unknown. */
bool keymap_canonical(const char* name, char* out, unsigned capacity);
#endif
